-- DLAB catalogue 2025: 183 products (instruments; accessories and spare parts not included).
-- Run once in Supabase -> SQL Editor (if a warning appears, choose "Run without RLS"). Safe to run again: updates by SKU.
-- Photos: /public/products/dlab/   Logo: /public/brands/dlab.png
alter table products add column if not exists features jsonb not null default '[]'::jsonb;

insert into brands (name, slug, website_url) values ('DLAB', 'dlab', 'https://www.dlabsci.com/')
on conflict (slug) do update set name = excluded.name, website_url = excluded.website_url;
insert into categories (name, slug, sort_order) values
  ('Equipment', 'equipment', 5), ('Life Science', 'life-science', 4),
  ('Spectrophotometer', 'spectrophotometer', 7), ('Environmental Equipment', 'environmental-equipment', 6)
on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('DLAB-CT4-Pro', 'DLAB CT4-Pro 4℃ Thermostatic Ice Box', 'dlab-ct4-pro-4-thermostatic-ice-box', 'DLAB CT4-Pro 4℃ Thermostatic Ice Box, part of the DLAB thermal control range.', '[["Model", "CT4-Pro"], ["Availability", "New arrival (coming soon)"]]', '["Fast cooling rate and high stability", "High-efficiency Peltier precision temperature control with good homogeneity", "Multi-colour LEDs to indicate different operating status", "Built-in temperature deviation calibration function, module alert function", "Compact product design, small footprint", "Multiple module choices, easy replacement of magnetic adsorption, suitable for a wide range of test tubes, and support for continuous operation", "It takes only about 10 minutes to reduce the temperature from room temperature to 4℃; -"]', 'life-science', '/products/dlab/p14.jpg'),
  ('DLAB-DMS7-550M', 'DLAB DMS7-550M Heated Magnetic Stirrer', 'dlab-dms7-550m-heated-magnetic-stirrer', 'DLAB DMS7-550M Heated Magnetic Stirrer, part of the DLAB stirring & heating range.', '[["Model", "DMS7-550M"], ["Work plate material", "Glass ceramic"], ["Motor type", "Brushless DC motor"], ["Stirring positions", "1"], ["Max. stirring quantity, [H2O]", "20L"], ["Max. magnetic bar[length]", "80mm"], ["Speed display", "LCD"], ["Temperature display", "LCD"], ["Heating output", "1150W"], ["Dimension [WxDxH]", "360x230x110mm"], ["Weight", "4.3kg"], ["Speed range", "-"], ["Heating temperature range", "-"], ["Temperature control accuracy", "-"], ["-", "10W"], ["Availability", "New arrival (coming soon)"]]', '["Ceramic discs are extremely corrosion-resistant, resistant to strong acids and alkalis, and high temperatures, making it easy to clean accidental drips of solvents, oils, or other contaminants", "The corrosion-resistant all-metal housing provides good heat dissipation and reliable fire protection", "High-efficiency infusion platform and waterproof edge design prevents liquid from entering the interior of the machine and corroding electronic components", "Selected high-temperature resistant strong magnetic magnet, strong stirring, suitable for viscous liquid stirring", "Heating modes are divided into: A rapid heating mode", "B standard heating mode, C stable heating mode, to meet different customer needs", "Safety locks to prevent accidental changes in operating conditions", "Buzzer: When the machine malfunctions, or the timer function counts down to the end of the buzzer will emit a \"drip drip drip\" sound", "Residual heat warning function, when the disc temperature is higher than 50 ℃, turn off the heating, the screen will have a \"HOT\" flashing prompt, even if the power off, the display is still \"HOT\" flashing to remind the high temperature", "Two independent safety circuits are designed to continuously monitor the equipment. When overheating occurs, the sensor fails, the machine reports an error and stops heating, and when the line is short-circuited, the machine automatically cuts off the power supply to protect the operator''s safety", "DC brushless motor, no spark, long life; low noise, maintenance-free, smooth running", "The LCD displays the set and real-time values of speed, time and temperature in an intuitive and clear manner"]', 'equipment', '/products/dlab/p18.jpg'),
  ('DLAB-DMS4-550', 'DLAB DMS4-550 Heated Magnetic Stirrer', 'dlab-dms4-550-heated-magnetic-stirrer', 'DLAB DMS4-550 Heated Magnetic Stirrer, part of the DLAB stirring & heating range.', '[["Model", "DMS4-550"], ["Work plate material", "Glass ceramic"], ["Motor type", "Brushless DC motor"], ["Stirring positions", "1"], ["Max. stirring quantity, [H2O]", "10L"], ["Max. magnetic bar[length]", "40mm"], ["Speed display", "LCD"], ["Temperature display", "LCD"], ["Heating output", "380W"], ["Dimension [WxDxH]", "270x175x108mm"], ["Weight", "2.2kg"], ["Speed range", "-"], ["Heating temperature range", "-"], ["Temperature control accuracy", "-"], ["-", "10W"], ["Availability", "New arrival (coming soon)"]]', '["Ceramic discs are extremely corrosion-resistant, resistant to strong acids and alkalis, and high temperatures, making it easy to clean accidental drips of solvents, oils, or other contaminants", "The corrosion-resistant all-metal housing provides good heat dissipation and reliable fire protection", "High-efficiency infusion platform and waterproof edge design prevents liquid from entering the interior of the machine and corroding electronic components", "Selected high-temperature resistant strong magnetic magnet, strong stirring, suitable for viscous liquid stirring", "Heating modes are divided into: A rapid heating mode", "B standard heating mode, C stable heating mode, to meet different customer needs", "Safety locks to prevent accidental changes in operating conditions", "Buzzer: When the machine malfunctions, or the timer function counts down to the end of the buzzer will emit a \"drip drip drip\" sound", "Residual heat warning function, when the disc temperature is higher than 50 ℃, turn off the heating, the screen will have a \"HOT\" flashing prompt, even if the power off, the display is still \"HOT\" flashing to remind the high temperature", "Two independent safety circuits are designed to continuously monitor the equipment. When overheating occurs, the sensor 