  ('DLAB-dFlow', 'DLAB dFlow Electronic Bottle-Top Dispenser', 'dlab-dflow-electronic-bottle-top-dispenser', 'Error-free, easy to use, motorized solution', '[["Model", "dFlow"]]', '[]', 'equipment', '/products/dlab/p80.jpg'),
